-- 19 September 2026 daily current-affairs desk.
-- Original revision briefs based on primary official releases published from 14 to 18 September.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
  $$2026-09-19-epfo-wage-ceiling-25000$$, $$2026-09-19$$,
  $$Cabinet raises the EPFO mandatory-coverage wage ceiling to ₹25,000$$,
  $$The Union Cabinet approved raising the wage ceiling for mandatory EPFO coverage from ₹15,000 to ₹25,000 per month. The official release estimates that more than 51 lakh additional employees will enter mandatory coverage once the statutory and administrative implementation steps are completed.$$,
  $$This is a major social-security and labour-formalisation development. Remember that the decision concerns the wage ceiling for mandatory coverage; the release also distinguishes EPFO’s three linked protections—provident fund, pension and deposit-linked insurance.$$,
  $$EPFO administers the Employees’ Provident Fund, the Employees’ Pension Scheme and the Employees’ Deposit Linked Insurance Scheme. Before this decision, a fresh employee joining above ₹15,000 a month was not automatically covered. The Cabinet decision raises that threshold to ₹25,000, with the Ministry of Labour & Employment and EPFO to take the required statutory and administrative steps for implementation.$$,
  $$Cabinet approves enhancement of EPFO wage ceiling from Rs.15,000 to Rs.25,000 per month$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2310812&lang=1&reg=3$$,
  $$Cabinet Secretariat and Ministry of Labour & Employment / Press Information Bureau$$, $$2026-09-16$$,
  $$["The approved wage ceiling for mandatory EPFO coverage rises from ₹15,000 to ₹25,000 per month.","The release estimates that more than 51 lakh additional employees may enter mandatory coverage.","EPFO administers EPF, the Employees’ Pension Scheme (EPS) and the Employees’ Deposit Linked Insurance Scheme (EDLI).","The final operational position depends on the necessary statutory and administrative implementation steps; Cabinet approval itself is not the same as a completed rollout."]$$::jsonb,
  $$[{"question":"What monthly wage ceiling did the Cabinet approve for mandatory EPFO coverage?","answer":"₹25,000, raised from ₹15,000."},{"question":"Name the three social-security arrangements administered by EPFO in the release.","answer":"EPF, EPS and EDLI."}]$$::jsonb,
  $${"title":"How the EPFO coverage change works","steps":["Cabinet approves a higher mandatory-coverage threshold.","The threshold rises from ₹15,000 to ₹25,000 per month.","More eligible employees can enter the EPF–EPS–EDLI social-security framework.","Statutory and administrative implementation follows the approval."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-19-wpi-august-2026$$, $$2026-09-19$$,
  $$August wholesale inflation is 9.92% on the new 2022–23 WPI base$$,
  $$India’s provisional all-commodity Wholesale Price Index inflation for August 2026 was 9.92% year-on-year, up from 9.78% in July. Fuel and Power recorded the highest inflation among the three major groups at 22.93%. $$,
  $$This is a core official-statistics item for economy questions. It tests the WPI base year, the distinction between provisional and final estimates, and the fact that WPI tracks wholesale—not retail—price movement.$$,
  $$The August release uses the WPI base year 2022–23. The all-commodities index was 110.8 in August, compared with 110.0 in July. Major-group year-on-year inflation was 7.76% for Primary Articles, 22.93% for Fuel and Power, and 8.37% for Manufactured Products. The release also revised the June final inflation estimate from 9.87% to 9.97%. $$,
  $$Provisional Estimates of Wholesale Price Index (Base Year 2022-23) for the month of August 2026$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2309977&lang=1&reg=3$$,
  $$Department for Promotion of Industry and Internal Trade, Ministry of Commerce & Industry / Press Information Bureau$$, $$2026-09-14$$,
  $$["August 2026 all-commodity WPI inflation was 9.92% year-on-year on the 2022–23 base.","The all-commodities WPI index was 110.8 in August 2026, compared with 110.0 in July.","Fuel and Power had the highest major-group inflation at 22.93%; Primary Articles and Manufactured Products recorded 7.76% and 8.37% respectively.","The August estimate is provisional; June 2026’s final WPI inflation was revised to 9.97%."]$$::jsonb,
  $$[{"question":"Which major WPI group had the highest year-on-year inflation in August 2026?","answer":"Fuel and Power, at 22.93%."},{"question":"What WPI base year is used in this release?","answer":"2022–23."}]$$::jsonb,
  $${"title":"Reading the August 2026 WPI release","steps":["DPIIT compiles the WPI on the 2022–23 base.","The August all-commodities index is 110.8.","Year-on-year movement produces 9.92% headline WPI inflation.","Major groups show the sources of wholesale-price pressure."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-19-india-mercosur-electronic-certificates-origin$$, $$2026-09-19$$,
  $$India–MERCOSUR protocol gives electronic Certificates of Origin equal legal validity$$,
  $$India and MERCOSUR signed the First Additional Protocol to their Preferential Trade Agreement to facilitate acceptance of electronic Certificates of Origin. The Protocol amends the Rules of Origin annex so qualifying electronic and paper certificates have the same legal validity and value.$$,
  $$This connects trade facilitation, Rules of Origin and regional economic groupings. The key nuance: the Protocol was signed, but it will enter into force only after the parties complete their internal procedures and notify one another.$$,
  $$The India–MERCOSUR PTA was signed on 25 January 2004 and entered into force on 1 June 2009. India offers preferential tariff concessions on 450 tariff lines and MERCOSUR on 452. The new Protocol amends Article 16 of Annex III, requiring electronic certificates to be issued and electronically signed by authorised entities under the relevant domestic law.$$,
  $$India and MERCOSUR Sign First Additional Protocol to Facilitate Electronic Certificates of Origin$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2310083&lang=1&reg=3$$,
  $$Ministry of Commerce & Industry / Press Information Bureau$$, $$2026-09-14$$,
  $$["The First Additional Protocol concerns electronic Certificates of Origin under the India–MERCOSUR PTA.","It amends Article 16 of Annex III, the PTA’s Rules of Origin annex.","Electronic and paper Certificates of Origin will have the same legal validity and value when issued as prescribed.","The Protocol enters into force only after the parties complete their respective internal procedures and notify each other."]$$::jsonb,
  $$[{"question":"Which PTA annex is amended by the First Additional Protocol?","answer":"Annex III on Rules of Origin, specifically Article 16."},{"question":"Has the Protocol automatically entered into force merely because it was signed?","answer":"No. It requires completion and notification of the parties’ internal procedures."}]$$::jsonb,
  $${"title":"From paper certificate to recognised electronic proof","steps":["A consignment claims a PTA preference only if origin rules are met.","A Certificate of Origin evidences that origin.","The Protocol gives qualifying electronic certificates the same legal validity as paper certificates.","Customs processing can move toward paperless verification after entry into force."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-19-india-mercosur-pta-expansion-negotiations$$, $$2026-09-19$$,
  $$India and MERCOSUR open negotiations to expand their Preferential Trade Agreement$$,
  $$India and MERCOSUR announced the launch of negotiations to expand their existing Preferential Trade Agreement. The sides are finalising Terms of Reference that will set the scope and structure of a future expanded agreement.$$,
  $$This is a foreign-trade and international-relations item. A Preferential Trade Agreement gives concessions on selected lines; the announcement starts negotiations for expansion and does not itself create a new free-trade agreement.$$,
  $$MERCOSUR is the Southern Common Market, whose original members are Argentina, Brazil, Paraguay and Uruguay. The existing India–MERCOSUR PTA entered into force in 2009. The fresh announcement is a negotiating step aimed at broader areas of mutual interest and deeper economic links.$$,
  $$Launching of negotiations for the expansion of the India–MERCOSUR Preferential Trade Agreement$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2310166&lang=1&reg=3$$,
  $$Ministry of Commerce & Industry / Press Information Bureau$$, $$2026-09-14$$,
  $$["India and MERCOSUR have launched negotiations to expand their existing Preferential Trade Agreement.","Terms of Reference are being finalised to define the scope and structure of the future expanded agreement.","A PTA is not automatically a comprehensive FTA; it normally provides preferences for specified goods or tariff lines.","MERCOSUR’s original members are Argentina, Brazil, Paraguay and Uruguay."]$$::jsonb,
  $$[{"question":"What is the immediate result of this announcement?","answer":"The launch of negotiations; it does not by itself create a new expanded agreement."},{"question":"Name the four original MERCOSUR members.","answer":"Argentina, Brazil, Paraguay and Uruguay."}]$$::jsonb,
  $${"title":"What an expanded PTA requires","steps":["India and MERCOSUR begin with an existing preferential trade arrangement.","Negotiators agree Terms of Reference.","The Terms define scope and structure for the expanded pact.","Only a concluded and completed agreement can change operative trade preferences."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-19-niti-india-electric-mobility-index-2025$$, $$2026-09-19$$,
  $$NITI Aayog publishes the second India Electric Mobility Index$$,
  $$NITI Aayog released the second edition of the India Electric Mobility Index (IEMI) 2025, a composite measure of State and Union Territory performance in electric-mobility policy and implementation. It was developed with WRI India and covers all 36 States and UTs.$$,
  $$The IEMI is useful for federalism, transport decarbonisation and evidence-based policy questions. It is an index and research tool—not a statutory allocation formula or a new EV subsidy scheme.$$,
  $$IEMI 2025 assesses the 2025 calendar year across transport-electrification progress, charging-infrastructure readiness, and EV research and innovation. To make comparisons fairer, it groups the 36 jurisdictions into 17 Large States, 12 Hilly and Northeastern States, and seven UTs and City States. Scores are out of 100, with categories ranging from Aspirants to Top Performers.$$,
  $$India Electric Mobility Index (IEMI) 2025$$,
  $$https://www.niti.gov.in/node/2424$$,
  $$NITI Aayog$$, $$2026-09-15$$,
  $$["IEMI 2025 is the second edition of NITI Aayog’s composite electric-mobility index, developed with WRI India.","It evaluates policy framework and implementation outcomes for all 36 States and Union Territories.","Its three themes are transport electrification progress, charging-infrastructure readiness, and EV research and innovation.","The report separates jurisdictions into Large States, Hilly and Northeastern States, and UTs and City States for peer comparison."]$$::jsonb,
  $$[{"question":"Is IEMI a new statutory EV-subsidy scheme?","answer":"No. It is a composite index used to assess policy and implementation performance."},{"question":"What are IEMI’s three assessment themes?","answer":"Transport electrification, charging-infrastructure readiness, and EV research and innovation."}]$$::jsonb,
  $${"title":"How IEMI compares e-mobility readiness","steps":["NITI Aayog and WRI India define common indicators.","States and UTs are compared within peer categories.","Theme scores capture policy and implementation conditions.","A composite score identifies relative progress and gaps for e-mobility transition."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-19-power-export-nepal-flood-response$$, $$2026-09-19$$,
  $$India approves temporary electricity exports to Nepal after flood damage$$,
  $$The Ministry of Power approved electricity exports to the Nepal Electricity Authority from 13 September through 31 December 2026 to address the additional demand created after floods damaged Nepal’s hydropower infrastructure.$$,
  $$This is a practical India–Nepal connectivity and neighbourhood-policy item. It links cross-border transmission capacity with disaster response; the approval is time-bound and specifies routes and capacities, rather than creating a permanent unconditional export commitment.$$,
  $$The approval covers up to 600 MW through the Muzaffarpur–Dhalkebar 400 kV double-circuit line and up to 54 MW through the Tanakpur–Mahendranagar 132 kV single-circuit line, for 18 hours daily from midnight to 18:00. The Ministry says the quantum from January 2027 will be reviewed in December 2026.$$,
  $$Export of Power to Nepal Approved$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2310017&lang=1&reg=3$$,
  $$Ministry of Power / Press Information Bureau$$, $$2026-09-14$$,
  $$["The approval runs from 13 September to 31 December 2026 and is linked to flood damage to Nepal’s hydropower infrastructure.","Up to 600 MW may be exported on the Muzaffarpur–Dhalkebar 400 kV double-circuit line.","Up to 54 MW may be exported on the Tanakpur–Mahendranagar 132 kV single-circuit line.","The daily export window is 00:00 to 18:00 hours, and the January 2027 quantum is to be reviewed in December 2026."]$$::jsonb,
  $$[{"question":"Which 400 kV transmission link is named in the approval?","answer":"The Muzaffarpur–Dhalkebar 400 kV double-circuit line."},{"question":"Is this approval open-ended?","answer":"No. It runs until 31 December 2026, with the later quantum subject to review."}]$$::jsonb,
  $${"title":"Cross-border power support to Nepal","steps":["Floods damage Nepal’s hydropower infrastructure.","Nepal faces an additional electricity requirement.","India authorises specified, time-bound flows on named interconnections.","The quantum is reviewed before any post-December arrangement."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-19-soil-carbon-payments-punjab-haryana$$, $$2026-09-19$$,
  $$India’s first soil-carbon payments reach 2,550 farmers in Punjab and Haryana$$,
  $$A Ludhiana programme initiated direct benefit transfers to 2,550 farmers in Punjab and Haryana for adopting regenerative farming practices, described in the official release as the first instance of Indian farmers receiving payment for carbon stored in soil. More than ₹2.9 crore is to be disbursed.$$,
  $$This is an emerging agriculture, climate-finance and carbon-market development. The source is reporting a verified pilot payment; students should not generalise it into a nationwide statutory soil-carbon payment scheme.$$,
  $$The initiative links field-level regenerative practices, scientific assessment and verification, and digital payments. It was held at Punjab Agricultural University with DARE/ICAR involvement. The release presents it as a Lab-to-Land example through research institutions, Agricultural Technology Application Research Institutes and Krishi Vigyan Kendras.$$,
  $$India’s First Soil Carbon Payments Put Farmers at the Centre of Regenerative Agriculture$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2311218&lang=1&reg=3$$,
  $$Department of Agricultural Research and Education and Indian Council of Agricultural Research / Press Information Bureau$$, $$2026-09-17$$,
  $$["The release reports digital soil-carbon payments to 2,550 farmers in Punjab and Haryana.","More than ₹2.9 crore is to be disbursed for regenerative-farming practices after assessment and verification.","The official release describes this as the first Indian instance of farmers being paid for carbon stored in their soil.","The initiative is connected with DARE/ICAR’s Lab-to-Land approach, including research institutions, ATARIs and KVKs."]$$::jsonb,
  $$[{"question":"Does the release describe a national statutory soil-carbon payment scheme?","answer":"No. It reports a verified payment initiative involving farmers in Punjab and Haryana."},{"question":"How many farmers received the DBT initiation in the release?","answer":"2,550 farmers."}]$$::jsonb,
  $${"title":"From regenerative practice to soil-carbon payment","steps":["Farmers adopt regenerative farming practices.","Soil-carbon outcomes undergo scientific assessment and verification.","Eligible farmers receive digital payments.","The pilot demonstrates a possible climate-income link at farm level."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-19-swachh-seva-aankalan-sbm-grameen$$, $$2026-09-19$$,
  $$Swachh Seva Aankalan launches annual Gram Panchayat sanitation self-assessment$$,
  $$The Department of Drinking Water and Sanitation launched Swachh Seva Aankalan, an annual Gram Panchayat-level digital self-assessment framework under Swachh Bharat Mission (Grameen) 2.0. It is designed to assess and monitor rural sanitation service delivery.$$,
  $$This is a strong decentralisation and rural-governance item. The process brings Gram Panchayats, Gram Sabhas, Village Water & Sanitation Committees and District/State authorities into one review chain, rather than treating sanitation as only a centrally measured programme.$$,
  $$ODF Plus (Model) declared Gram Panchayats, their Village Water & Sanitation Committees and communities assess ODF sustainability, visual cleanliness, and solid and liquid waste management. Findings are discussed and validated in the Gram Sabha, then reviewed by District and State/UT authorities to prepare improvement plans.$$,
  $$Department of Drinking Water & Sanitation launches Swachh Seva Aankalan for Swachh Bharat Mission (Grameen)$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2310773&lang=1&reg=3$$,
  $$Department of Drinking Water and Sanitation, Ministry of Jal Shakti / Press Information Bureau$$, $$2026-09-16$$,
  $$["Swachh Seva Aankalan is an annual, Gram Panchayat-level digital self-assessment under SBM (Grameen) 2.0.","It assesses rural sanitation delivery, including ODF sustainability, visual cleanliness and solid and liquid waste management.","The framework involves Gram Panchayats, Gram Sabhas, Village Water & Sanitation Committees, and District and State/UT officials.","Gram Sabha validation feeds into district and State/UT review and local improvement plans."]$$::jsonb,
  $$[{"question":"Which mission hosts Swachh Seva Aankalan?","answer":"Swachh Bharat Mission (Grameen) 2.0."},{"question":"Which local forum validates the assessment findings?","answer":"The concerned Gram Sabha."}]$$::jsonb,
  $${"title":"Swachh Seva Aankalan accountability loop","steps":["The Gram Panchayat and community self-assess sanitation services.","The Gram Sabha discusses and validates the findings.","District and State/UT bodies review the results.","Authorities identify gaps and prepare improvement plans."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-19-trai-tcccpr-third-amendment$$, $$2026-09-19$$,
  $$TRAI issues the third amendment to its commercial-communications preference rules$$,
  $$TRAI released the Telecom Commercial Communications Customer Preference (Third Amendment) Regulations, 2026 on 18 September. The measure is a formal amendment to the regulator’s commercial-communications customer-preference framework, not merely the earlier consultation draft.$$,
  $$This is a telecommunications-regulation item. For prelims, separate the regulator, TRAI, from the underlying framework: the main Telecom Commercial Communication Customer Preference Regulations date to 2018, with amendments in 2018, 2025 and now 2026.$$,
  $$TRAI’s official regulations page lists the main 2018 regulations, the first amendment in December 2018, the second amendment in February 2025, and the third amendment in September 2026. The current update was released by the Quality of Service division and forms part of the framework governing commercial communications and customer preferences.$$,
  $$The Telecom Commercial Communications Customer Preference (Third Amendment) Regulations, 2026$$,
  $$https://trai.gov.in/release-publication/regulations/amendments-page/7617$$,
  $$Telecom Regulatory Authority of India$$, $$2026-09-18$$,
  $$["TRAI released the Telecom Commercial Communications Customer Preference (Third Amendment) Regulations, 2026 on 18 September 2026.","The underlying Telecom Commercial Communication Customer Preference Regulations are from 2018.","The regulations page lists a first amendment in 2018, a second amendment in 2025 and the third amendment in 2026.","The update is a regulation, distinct from the draft consultation that preceded it."]$$::jsonb,
  $$[{"question":"Which regulator issued the third amendment to the commercial-communications preference rules?","answer":"The Telecom Regulatory Authority of India (TRAI)."},{"question":"Was the 18 September publication a consultation draft?","answer":"No. It was the released third amendment regulation."}]$$::jsonb,
  $${"title":"TRAI’s commercial-communications regulation chain","steps":["TRAI issued the main customer-preference framework in 2018.","The framework received amendments in 2018 and 2025.","TRAI released the third amendment on 18 September 2026.","The operative framework is read as the main regulations plus applicable amendments."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-19-mukutban-gadchandur-new-rail-line$$, $$2026-09-19$$,
  $$Railways approves ₹493 crore Mukutban–Gadchandur line for freight connectivity$$,
  $$Indian Railways approved a 38.21 km new rail line between Mukutban in Yavatmal and Gadchandur in Chandrapur at a cost of ₹493 crore. The project is intended to serve coal, cement, limestone and other industrial traffic while reducing pressure on the Wardha–Manikgarh section.$$,
  $$This is a targeted infrastructure-development brief that tests the location, rail-corridor logic and freight-led rationale. It is an approval for a new line, not a statement that the corridor is already operational.$$,
  $$The release identifies the two locations as industrial and mining centres, with cement plants, Western Coalfields mines and limestone mines nearby. According to the Detailed Project Report, the line is expected to support 6.08 million tonnes per annum of freight after commissioning and provide an alternative to the congested Balharshah–Nagpur high-density route.$$,
  $$Indian Railways Approves ₹493 Crore for 38.21 km New Rail Line between Mukutban (Adilabad) and Gadchandur$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2311827&lang=1&reg=3$$,
  $$Ministry of Railways / Press Information Bureau$$, $$2026-09-18$$,
  $$["The approved Mukutban–Gadchandur new line is 38.21 km long and costs ₹493 crore.","Mukutban is in Yavatmal district and Gadchandur is in Chandrapur district.","The project is designed to improve freight access for coal, cement, limestone and related industrial traffic.","The Detailed Project Report estimates 6.08 MTPA freight traffic after commissioning and an alternative to the Balharshah–Nagpur high-density route."]$$::jsonb,
  $$[{"question":"Which two districts are linked by the approved new line?","answer":"Yavatmal and Chandrapur in Maharashtra."},{"question":"What freight capacity does the Detailed Project Report project after commissioning?","answer":"6.08 MTPA."}]$$::jsonb,
  $${"title":"Why the Mukutban–Gadchandur line was approved","steps":["Industrial and mining clusters need better rail access.","A new 38.21 km connection links Mukutban and Gadchandur.","Freight can take a shorter route toward the Majri–Nanded corridor.","The line can ease congestion on the Balharshah–Nagpur high-density network."]}$$::jsonb,
  $$published$$, now()
)
